begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at,raw_app_meta_data,raw_user_meta_data)values('00000000-0000-4000-8000-000000191601','authenticated','authenticated','s191-sites-a@veyocast.test','test',now(),now(),now(),'{}','{}'),('00000000-0000-4000-8000-000000191602','authenticated','authenticated','s191-sites-b@veyocast.test','test',now(),now(),now(),'{}','{}');
insert into public.profiles(id,display_name)values('00000000-0000-4000-8000-000000191601','Sites owner A'),('00000000-0000-4000-8000-000000191602','Sites owner B');
insert into public.tenants(id,name,slug)values('10000000-0000-4000-8000-000000191601','Sites tenant A','s191-sites-a'),('10000000-0000-4000-8000-000000191602','Sites tenant B','s191-sites-b');
insert into public.tenant_settings(tenant_id)values('10000000-0000-4000-8000-000000191601'),('10000000-0000-4000-8000-000000191602');
insert into public.tenant_memberships(tenant_id,user_id,role)values('10000000-0000-4000-8000-000000191601','00000000-0000-4000-8000-000000191601','tenant_owner'),('10000000-0000-4000-8000-000000191602','00000000-0000-4000-8000-000000191602','tenant_owner');
create temporary table sites_fixtures(name text primary key,value jsonb);
insert into sites_fixtures values('document','{"schemaVersion":1,"artboard":{"width":1920,"height":1080,"orientation":"landscape","background":{"kind":"solid","color":"#FAFAF7"},"safeArea":{"top":64,"right":64,"bottom":64,"left":64}},"motion":{"enabled":false,"durationMs":15000,"fps":30},"elements":[],"metadata":{"fontRegistryVersion":"2026-07-24.1","tenantBrandApplied":false},"sitesPresentation":{"kind":"studio","schemaVersion":1,"rendererVersion":"sites-v11","sourceRevision":"b1cae899af19fc39908217253094c5240d7359fc","slide":{"id":"s191-fixture","name":"Typed club update","title":"Onze club","time":"","subtitle":"","location":"","duration":15,"color":"#03438a","background":"#052a55","bold":true,"italic":false,"align":"left","size":58,"context":true,"showLocation":true,"animation":"Geen","transition":"Rustig","orientation":"landscape","themeId":"onzetrots-tv","tv":{"kind":"programma","title":"Onze club","rows":[{"id":"fixture-match","primary":"Team A","home":"Team A","away":"Team B","time":"14:00"}],"scale":100}}}}'::jsonb),('configuration','{"schemaVersion":1,"rendererVersion":"sites-v11","sourceRevision":"b1cae899af19fc39908217253094c5240d7359fc","themeId":"onzetrots-tv","orientation":"landscape","provider":"sportlink","title":"Stand","subtitle":"","overlay":25,"accent":"#03438a","layout":"full","scale":100,"align":"left","safeArea":4,"seconds":15,"rowsPerPage":8,"ledTheme":"blue","ledMoment":"live","ledSide":"unknown","titleScale":100,"scoreScale":100,"logoScale":100,"teamScale":100,"showBranding":true,"showSceneLabel":true,"showClock":true,"showTimeline":true,"timelineLimit":3,"backgroundFit":"contain","grunge":55,"animation":"rise"}'::jsonb);
grant select on sites_fixtures to authenticated;

select is((select count(*)from public.tenant_theme_profiles where tenant_id='10000000-0000-4000-8000-000000191601'),2::bigint,'new tenants provision both authorable screen themes');
select ok(not has_function_privilege('anon','private.assert_sites_assets_v1(uuid,jsonb)','EXECUTE'),'anonymous cannot call asset admission helper');
select ok(not has_function_privilege('authenticated','private.sites_configuration_is_valid_v1(jsonb)','EXECUTE'),'browser cannot call private schema helper');
select ok(private.sites_configuration_is_valid_v1((select value from sites_fixtures where name='configuration')),'normalized configuration fits bounded typed schema');
select ok(not private.sites_configuration_is_valid_v1((select value-'seconds' from sites_fixtures where name='configuration')),'missing required fields fail closed');
select ok(not private.sites_configuration_is_valid_v1((select value||'{"rawProviderUrl":"https://example.invalid"}' from sites_fixtures where name='configuration')),'unknown network metadata is rejected');
select ok(not private.sites_configuration_is_valid_v1((select jsonb_set(value,'{scale}','145')from sites_fixtures where name='configuration')),'standard content cannot use LED-only scale');
select lives_ok($$select private.assert_studio_document('10000000-0000-4000-8000-000000191601','landscape',1920,1080,(select value from sites_fixtures where name='document'),'{}'::uuid[])$$,'trusted Sites document accepted by existing Studio admission');
select throws_ok($$select private.assert_studio_document('10000000-0000-4000-8000-000000191601','landscape',1920,1080,(select jsonb_set(value,'{sitesPresentation,sourceRevision}','"0000000000000000000000000000000000000000"')from sites_fixtures where name='document'),'{}'::uuid[])$$,'23514','Sites Studio identity invalid','untrusted renderer revision rejected');
select throws_ok($$select private.assert_sites_assets_v1('10000000-0000-4000-8000-000000191601','{"photo":"https://example.invalid/member.png"}')$$,'23514','Sites images require verified identities','raw image URL cannot reach capture');
select throws_ok($$select private.assert_sites_assets_v1('10000000-0000-4000-8000-000000191601','{"photo":{"kind":"system","path":"/onzetrots-tv/assets/logo.png","checksumSha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}}')$$,'23514','Sites system identity invalid','changed system checksum rejected');
select throws_ok($$select private.assert_sites_assets_v1('10000000-0000-4000-8000-000000191601','{"photo":{"kind":"tenant","mediaAssetId":"20000000-0000-4000-8000-000000191602","checksumSha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}}')$$,'23514','Sites media unavailable in this tenant','unavailable or cross-tenant image rejected');
select throws_ok($$select private.assert_sites_assets_v1('10000000-0000-4000-8000-000000191601','{"brandLogo":"https://example.invalid/logo.png"}')$$,'23514','Sites images require verified identities','brand fallback cannot carry a raw URL');
select lives_ok($$select private.assert_sites_assets_v1('10000000-0000-4000-8000-000000191601','{"brandLogo":{"kind":"system","path":"/onzetrots-tv/assets/logo.png","checksumSha256":"832c642ea9735b87452a6508ae5525f4f87fe528408efc58ad0f86f1a456a930"}}')$$,'audited immutable brand identity is admitted');
select throws_ok($$select private.assert_sites_assets_v1('10000000-0000-4000-8000-000000191601','{"brandLogo":{"kind":"system","path":"/onzetrots-tv/assets/logo.png","checksumSha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}}')$$,'23514','Sites system identity invalid','brand fallback checksum mismatch is rejected');
insert into public.media_assets(id,tenant_id,kind,title,original_file_name,mime_type,status,storage_path,file_size_bytes,checksum_sha256)values('20000000-0000-4000-8000-000000191602','10000000-0000-4000-8000-000000191602','image','Other tenant brand','logo.png','image/png','ready','tenants/10000000-0000-4000-8000-000000191602/assets/20000000-0000-4000-8000-000000191602/original/logo.png',1024,repeat('a',64));
insert into public.media_variants(id,tenant_id,asset_id,variant_type,storage_path,mime_type,file_size_bytes,checksum_sha256)values('90000000-0000-4000-8000-000000191602','10000000-0000-4000-8000-000000191602','20000000-0000-4000-8000-000000191602','original','tenants/10000000-0000-4000-8000-000000191602/assets/20000000-0000-4000-8000-000000191602/original/logo.png','image/png',1024,repeat('a',64));
select throws_ok($$select private.assert_sites_assets_v1('10000000-0000-4000-8000-000000191601','{"brandLogo":{"kind":"tenant","mediaAssetId":"20000000-0000-4000-8000-000000191602","checksumSha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}}')$$,'23514','Sites media unavailable in this tenant','even a real verified tenant B logo is rejected by tenant A');
create function pg_temp.switch_sites_theme(p_theme text,p_version text)returns jsonb language sql as $$select public.update_tenant_theme_settings_v3(profile.tenant_id,profile.revision,p_theme,p_version,profile.selection_json->'modePolicy',profile.color_overrides,profile.appearance_config,profile.selection_json->>'accent',profile.selection_json->>'support')from public.tenant_theme_profiles profile where profile.tenant_id='10000000-0000-4000-8000-000000191601' and profile.theme_id=p_theme$$;
set local role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000191601',true);
select lives_ok($$select pg_temp.switch_sites_theme('onzetrots-tv','11.0.0')$$,'tenant owner switches to saved TV profile');
select is((select default_theme_id from public.tenant_settings where tenant_id='10000000-0000-4000-8000-000000191601'),'onzetrots-tv','active default really switches');
select lives_ok($$select pg_temp.switch_sites_theme('fieldflow','1.0.0')$$,'switching back to identical saved FieldFlow profile is applied');
select is((select default_theme_id from public.tenant_settings where tenant_id='10000000-0000-4000-8000-000000191601'),'fieldflow','identical target profile does not create a false noop');
select is((select count(*)from public.tenant_theme_profiles where tenant_id='10000000-0000-4000-8000-000000191602'),0::bigint,'tenant A cannot read tenant B theme profiles');
reset role;
select lives_ok($$select private.apply_tenant_theme_to_snapshot_v1('10000000-0000-4000-8000-000000191601','{"sport":{"items":[{"id":"row-preserved","form":["win","loss"]}]},"type":"sport_standing"}','30000000-0000-4000-8000-000000191601')$$,'new wrapper retains current runtime and timezone pipeline');
select is(private.apply_tenant_theme_to_snapshot_v1('10000000-0000-4000-8000-000000191601','{"sport":{"items":[{"id":"row-preserved","form":["win","loss"]}]},"type":"sport_standing"}','30000000-0000-4000-8000-000000191601')#>>'{sport,items,0,id}','row-preserved','provider-owned row survives theme rollout');
select is(private.apply_tenant_theme_to_snapshot_v1('10000000-0000-4000-8000-000000191601','{"sport":{"items":[]},"type":"sport_standing"}','30000000-0000-4000-8000-000000191601')#>>'{_veyocastThemeRuntime,version}','2','S159 runtime marker is retained');

-- Optional knobs remain backwards compatible at the SQL boundary and use real guarded saves.
select ok(private.sites_configuration_is_valid_v1((select value from sites_fixtures where name='configuration')),'legacy configurations need neither additive knob');
select ok(private.sites_configuration_is_valid_v1((select value||'{"showCategories":false,"ledTemplate":"scoreboard"}'::jsonb from sites_fixtures where name='configuration')),'typed additive knobs are admitted');
select ok(not private.sites_configuration_is_valid_v1((select value||'{"showCategories":"false"}'::jsonb from sites_fixtures where name='configuration')),'string false cannot masquerade as category boolean');
select ok(not private.sites_configuration_is_valid_v1((select value||'{"ledTemplate":"wrong-mode"}'::jsonb from sites_fixtures where name='configuration')),'unknown LED display mode fails closed');
select ok(not private.sites_configuration_is_valid_v1((select value||'{"showCategories":false,"unknownKnob":true}'::jsonb from sites_fixtures where name='configuration')),'additive knobs do not open the unknown-field boundary');
update public.tenant_settings set menu_document_v2_read_enabled=true,menu_studio_v2_authoring_enabled=true where tenant_id='10000000-0000-4000-8000-000000191601';
insert into public.tenant_feature_flags(tenant_id,flag_key,enabled,rollout_reason,changed_by)values('10000000-0000-4000-8000-000000191601','ledscores_realtime',true,'S191 optional knob persistence fixture','00000000-0000-4000-8000-000000191601');
insert into public.screen_groups(id,tenant_id,name,created_by,updated_by)values('31000000-0000-4000-8000-000000191601','10000000-0000-4000-8000-000000191601','Optional knob targets','00000000-0000-4000-8000-000000191601','00000000-0000-4000-8000-000000191601');
create temporary table sites_saved(name text primary key,value jsonb);
grant all on sites_saved to authenticated;
set local role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000191601',true);
select set_config('test.s191sites_menu_source',public.create_dynamic_data_source_v1('10000000-0000-4000-8000-000000191601','Optional menu source','manual_products','{}')::text,true);
insert into sites_saved select 'menu-created',public.create_menu_studio_draft_v2('10000000-0000-4000-8000-000000191601','Optional menu',(select version.id from public.dynamic_template_versions version join public.dynamic_templates template on template.id=version.template_id where template.slide_type='price_list' and template.orientation='landscape' and template.current_published_version_id=version.id and version.status='published' limit 1),current_setting('test.s191sites_menu_source')::uuid,'latest','{"schemaVersion":"menu-document.v2","id":"draft","tenantId":"draft","revision":1,"createdAt":"2026-10-11T10:00:00Z","updatedAt":"2026-10-11T10:00:00Z","title":"Menu","theme":{"themeId":"onzetrots-tv","themeVersion":"11.0.0","mode":"light","brand":{"accent":"#03438a"}},"assets":[],"pages":[{"id":"page-1","order":0,"blocks":[]}]}','20000000-0000-4000-8000-000000191691');
insert into sites_saved select 'menu-saved',public.save_menu_studio_document_v2((value->>'slideId')::uuid,1,'20000000-0000-4000-8000-000000191692',jsonb_build_object('kind','set-sites-configuration','sitesConfiguration',(select value||'{"provider":"menu","showCategories":false}'::jsonb from sites_fixtures where name='configuration')),jsonb_set(value->'document','{sitesConfiguration}',(select value||'{"provider":"menu","showCategories":false}'::jsonb from sites_fixtures where name='configuration')))from sites_saved where name='menu-created';
select is((select value->>'outcome'from sites_saved where name='menu-saved'),'applied','category-off configuration saves through real revision-aware Menu RPC');
select is((select configuration_json#>'{sitesConfiguration,showCategories}'from public.dynamic_slides where id=(select(value->>'slideId')::uuid from sites_saved where name='menu-created')),'false'::jsonb,'Menu reload preserves boolean false without default replacement');
select throws_ok($$select public.save_menu_studio_document_v2((select(value->>'slideId')::uuid from sites_saved where name='menu-created'),2,'20000000-0000-4000-8000-000000191693','{"kind":"set-sites-configuration"}',(select jsonb_set(value->'document','{sitesConfiguration,showCategories}','"false"')from sites_saved where name='menu-saved'))$$,'23514','Sites Menu configuration invalid','guarded Menu save rejects string false');
select is((select menu_document_revision from public.dynamic_slides where id=(select(value->>'slideId')::uuid from sites_saved where name='menu-created')),2::bigint,'rejected flag input leaves the last good Menu revision active');
select lives_ok($$select public.save_ledscores_connection_v1('10000000-0000-4000-8000-000000191601',null,'Optional LED','s191-optional-led','active',0)$$,'LED fixture connection uses the existing guarded connector RPC');
select set_config('test.s191sites_led_connection',(select id::text from public.ledscores_connections where tenant_id='10000000-0000-4000-8000-000000191601'),true);
reset role;
insert into sites_fixtures select 'led-config',jsonb_build_object('schemaVersion',1,'triggerOwn',true,'triggerOpponent',false,'unknownPolicy','suppress','ownTeamKeys','[]'::jsonb,'activeFrom',null,'activeUntil',null,'ownSoundVolume',70,'opponentSoundVolume',0,'sponsorOnlyOwn',true,'ownDesign','{"headline":"Goal","animation":"impact","palette":"electric-orange"}'::jsonb,'opponentDesign','{"headline":"Doelpunt","animation":"pulse","palette":"ink-black"}'::jsonb,'unknownDesign','{"headline":"Goal","animation":"impact","palette":"ink-black"}'::jsonb,'canvasExperience',jsonb_build_object('schemaVersion',1,'scenes',(select jsonb_object_agg(moment,jsonb_build_object('landscape',jsonb_build_object('orientation','landscape','background','{"kind":"solid","color":"#03438a"}'::jsonb,'layers','[]'::jsonb,'sitesConfiguration',(select value||'{"provider":"led-scores","ledMoment":"goal","ledTemplate":"scoreboard"}'::jsonb from sites_fixtures where name='configuration')),'portrait',jsonb_build_object('orientation','portrait','background','{"kind":"solid","color":"#03438a"}'::jsonb,'layers','[]'::jsonb)))from unnest(array['goalOwn','goalOpponent','goalUnknown','lineupHome','lineupAway','matchStart','halfTime','matchEnd'])moment)));
set local role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000191601',true);
insert into sites_saved select 'led-saved',public.save_ledscores_goal_alert_v1('10000000-0000-4000-8000-000000191601',null,current_setting('test.s191sites_led_connection')::uuid,'Optional LED mode',500,8000,'continue',(select value from sites_fixtures where name='led-config'),array['31000000-0000-4000-8000-000000191601']::uuid[],'{}'::uuid[],0);
select is((select value->>'outcome'from sites_saved where name='led-saved'),'saved','scoreboard configuration saves through the real guarded LED RPC');
select is((select draft_config#>>'{canvasExperience,scenes,goalOwn,landscape,sitesConfiguration,ledTemplate}'from public.ledscores_goal_alerts where tenant_id='10000000-0000-4000-8000-000000191601'),'scoreboard','LED reload preserves the selected immutable scene mode');
select throws_ok($$select public.save_ledscores_goal_alert_v1('10000000-0000-4000-8000-000000191601',(select id from public.ledscores_goal_alerts where tenant_id='10000000-0000-4000-8000-000000191601'),current_setting('test.s191sites_led_connection')::uuid,'Bad LED mode',500,8000,'continue',(select jsonb_set(value,'{canvasExperience,scenes,goalOwn,landscape,sitesConfiguration,ledTemplate}','"bad-mode"')from sites_fixtures where name='led-config'),array['31000000-0000-4000-8000-000000191601']::uuid[],'{}'::uuid[],1)$$,'23514','invalid LED Scores Sites scene','guarded LED save rejects an unknown mode');
select is((select revision from public.ledscores_goal_alerts where tenant_id='10000000-0000-4000-8000-000000191601'),1::integer,'bad LED mode does not advance the active draft');
reset role;
select *from finish();rollback;
